import { and, desc, eq } from "drizzle-orm"

import type { RelatedGraph, RelatedLink } from "@workspace/shared"

import type { RequestContext } from "../context"
import { memories } from "../db/schema"

/** Matches the graph builder's cap, so the two views describe the same set of memories. */
const MAX_MEMORIES = 400

/**
 * Neighbours kept per memory.
 *
 * This is a k-nearest-neighbour graph, not a threshold sweep: keeping the best few per memory
 * bounds the payload at `n * k` regardless of how similar the corpus happens to be. A pure
 * threshold has no such bound — one tightly-themed corpus would return every pair.
 */
const NEIGHBOURS_PER_MEMORY = 6

/**
 * Floor below which a pair is never emitted at all.
 *
 * NOT TUNED. It cannot be from here: the right value depends on this embedding model and on the
 * shape of a real corpus, and the only data available to check it against was four memories —
 * six pairs, no distribution, no elbow to read. So this is deliberately permissive and the real
 * cutoff is left to the reader, who moves a slider and watches the graph respond. Once there are
 * a few hundred memories, plot these scores and this constant can become a measurement.
 */
const MINIMUM_SCORE = 0.3

/**
 * Infer "these two mean similar things" edges from the stored embeddings.
 *
 * Split from `buildGraph` on purpose. This path fans out to Vectorize and then does O(n²) work,
 * while the structural graph is a couple of indexed D1 reads — folding them together would make
 * every graph load wait on the slow half. The client draws the shells first and lets these arrive.
 */
export async function buildRelated(ctx: RequestContext): Promise<RelatedGraph> {
  if (!ctx.vectors) return { links: [], available: false, compared: 0 }

  const rows = await ctx.db
    .select({ id: memories.id })
    .from(memories)
    .where(and(eq(memories.userId, ctx.userId), eq(memories.status, "active")))
    .orderBy(desc(memories.createdAt))
    .limit(MAX_MEMORIES)

  if (rows.length < 2)
    return { links: [], available: false, compared: rows.length }

  const stored = await ctx.vectors.fetchVectors(rows.map((row) => row.id))

  // Only memories that actually have a vector can take part. Anything still `pending` or `failed`
  // is skipped rather than treated as dissimilar, which would be a lie about it.
  const ids: string[] = []
  const unit: number[][] = []
  for (const row of rows) {
    const vector = stored.get(row.id)
    if (!vector) continue

    // Pre-normalised so each comparison below is a plain dot product rather than a division.
    // Summed in a loop, not `Math.hypot(...vector)` — spreading 1536 arguments risks the stack.
    let sumOfSquares = 0
    for (const value of vector) sumOfSquares += value * value
    const length = Math.sqrt(sumOfSquares)
    if (length === 0) continue
    ids.push(row.id)
    unit.push(vector.map((value) => value / length))
  }

  if (ids.length < 2)
    return { links: [], available: true, compared: ids.length }

  const dimensions = unit[0]!.length
  const best = new Map<string, number>()

  const remember = (a: number, b: number, score: number) => {
    if (score < MINIMUM_SCORE) return
    // One key per unordered pair, so a mutual neighbour is not emitted twice.
    const key = a < b ? `${ids[a]}�${ids[b]}` : `${ids[b]}�${ids[a]}`
    const existing = best.get(key)
    if (existing === undefined || score > existing) best.set(key, score)
  }

  for (let i = 0; i < unit.length; i++) {
    const left = unit[i]!
    // Only the top few per memory survive, tracked as a small running list rather than by sorting
    // the whole row — at 400 memories that is 400 sorts of 400 avoided.
    const top: Array<{ index: number; score: number }> = []

    for (let j = 0; j < unit.length; j++) {
      if (i === j) continue
      const right = unit[j]!

      let dot = 0
      for (let d = 0; d < dimensions; d++) dot += left[d]! * right[d]!
      if (dot < MINIMUM_SCORE) continue

      if (top.length < NEIGHBOURS_PER_MEMORY) {
        top.push({ index: j, score: dot })
        top.sort((a, b) => a.score - b.score)
      } else if (dot > top[0]!.score) {
        top[0] = { index: j, score: dot }
        top.sort((a, b) => a.score - b.score)
      }
    }

    for (const neighbour of top) remember(i, neighbour.index, neighbour.score)
  }

  const links: RelatedLink[] = [...best].map(([key, score]) => {
    const [source, target] = key.split("�")
    return { source: source!, target: target!, score }
  })
  links.sort((a, b) => b.score - a.score)

  return { links, available: true, compared: ids.length }
}
