import { inputRequired } from "@modelcontextprotocol/server"
import type {
  AuthInfo,
  CallToolResult,
  InputRequiredResult,
  McpServer,
  ServerContext,
} from "@modelcontextprotocol/server"
import type { ProposeResult } from "@workspace/shared"
import {
  PROPOSE_MEMORY,
  SEARCH_MEMORY,
  proposeMemoryArgs,
  searchMemoryArgs,
  threadArg,
} from "@workspace/shared"
import { z } from "zod"

import { describe } from "../chat/tools"
import type { RequestContext } from "../context"
import type { Env } from "../env"
import { sha256Hex } from "../lib/hash"
import { findContext, resolveProject } from "../memory/containers"
import { getOutcome, propose } from "../memory/negotiation"
import { searchMemories } from "../memory/retrieval"
import { SCOPE_PROPOSE, SCOPE_READ, resolveOrigin } from "./config"
import { contextFromToken, hasScope } from "./auth"
import type { ProposalState } from "./state"
import type { RequestStateCodec } from "@modelcontextprotocol/server"

/**
 * The same two tools the built-in agent has, over MCP. Contracts come from
 * `@workspace/shared/tools` so the two surfaces cannot drift.
 *
 * `session` scope needs a conversation, and MCP has none — `2026-07-28` removed protocol
 * sessions entirely. So both tools take an optional `thread`, following the spec's guidance
 * for stateful tools: hand the client an explicit handle rather than infer one.
 */
const searchArgsWithThread = searchMemoryArgs.extend({ thread: threadArg })
const proposeArgsWithThread = proposeMemoryArgs.extend({ thread: threadArg })

export interface ToolDeps {
  env: Env
  codec: RequestStateCodec<ProposalState>
  waitUntil?: (promise: Promise<unknown>) => void
}

/**
 * Map a client-chosen thread to the `conversationId` the domain expects.
 *
 * Hashed with the OAuth client id so two agents cannot collide — or worse, guess — each
 * other's threads. `contexts` is keyed `(user_id, conversation_id)` and the user comes from
 * the token, so the derived value only ever addresses a context inside the caller's own
 * account; the client prefix keeps agents separated within it.
 */
async function threadToConversationId(
  clientId: string,
  thread: string | undefined
): Promise<string | undefined> {
  if (!thread) return undefined
  return `mcp_${(await sha256Hex(`${clientId}�${thread}`)).slice(0, 32)}`
}

/** A tool result the model can act on, for a scope the token does not carry. */
function missingScope(scope: string): CallToolResult {
  return {
    content: [
      {
        type: "text",
        text:
          `This token does not carry the "${scope}" scope, so the call was refused. ` +
          `Ask the user to reconnect this application and grant it.`,
      },
    ],
    isError: true,
  }
}

function text(
  body: string,
  structured?: Record<string, unknown>
): CallToolResult {
  return {
    content: [{ type: "text", text: body }],
    ...(structured ? { structuredContent: structured } : {}),
    isError: false,
  }
}

/**
 * Does the client accept a URL-mode elicitation?
 *
 * The spec forbids sending a mode the client has not declared, and this is also the switch
 * that makes older clients work: a 2025-era client never declares `elicitation.url`, so it
 * automatically takes the plain-text path instead of being sent something it cannot render.
 */
function acceptsUrlElicitation(server: McpServer): boolean {
  return Boolean(server.server.getClientCapabilities()?.elicitation?.url)
}

function authOf(ctx: ServerContext): AuthInfo | undefined {
  return ctx.http?.authInfo
}

export function registerMemoryTools(server: McpServer, deps: ToolDeps): void {
  // -------------------------------------------------------------------------
  // search_memory
  // -------------------------------------------------------------------------

  server.registerTool(
    SEARCH_MEMORY.name,
    {
      title: SEARCH_MEMORY.title,
      description: SEARCH_MEMORY.description,
      inputSchema: searchArgsWithThread,
      outputSchema: z.object({
        memories: z.array(
          z.object({
            id: z.string(),
            fact: z.string(),
            scope: z.string(),
            category: z.string().nullable(),
          })
        ),
      }),
      annotations: SEARCH_MEMORY.annotations,
    },
    async (args, ctx): Promise<CallToolResult> => {
      const auth = authOf(ctx)
      if (!auth) return missingScope(SCOPE_READ)
      if (!hasScope(auth, SCOPE_READ)) return missingScope(SCOPE_READ)

      const request = contextFromToken(deps.env, auth, deps.waitUntil)
      const conversationId = await threadToConversationId(
        auth.clientId,
        args.thread
      )

      const [projectId, contextId] = await Promise.all([
        resolveProject(request.db, request.userId, args.projectKey, {
          create: false,
        }),
        findContext(request.db, request.userId, conversationId),
      ])

      const results = await searchMemories(request, {
        query: args.query,
        projectId,
        contextId,
        categories: args.categories,
        limit: args.limit,
      })

      const memories = results.map((memory) => ({
        id: memory.id,
        fact: memory.fact,
        scope: memory.scope,
        category: memory.category,
      }))

      return text(
        results.length === 0
          ? "No stored memories match that, within what is visible here."
          : results
              .map(
                (memory) => `[${memory.id} · ${memory.scope}] ${memory.fact}`
              )
              .join("\n"),
        { memories }
      )
    }
  )

  // -------------------------------------------------------------------------
  // propose_memory — the consent round-trip
  // -------------------------------------------------------------------------

  server.registerTool(
    PROPOSE_MEMORY.name,
    {
      title: PROPOSE_MEMORY.title,
      description:
        PROPOSE_MEMORY.description +
        " Approval happens in the user's browser, not through you: expect to be asked to " +
        "open a link and then retry this call to collect the outcome.",
      inputSchema: proposeArgsWithThread,
      annotations: PROPOSE_MEMORY.annotations,
    },
    async (args, ctx): Promise<CallToolResult | InputRequiredResult> => {
      const auth = authOf(ctx)
      if (!auth) return missingScope(SCOPE_PROPOSE)
      if (!hasScope(auth, SCOPE_PROPOSE)) return missingScope(SCOPE_PROPOSE)

      const request = contextFromToken(deps.env, auth, deps.waitUntil)
      const origin = originOf(ctx, deps.env)

      /**
       * Round two or later. The state has already been through the codec's `verify` by the
       * time we are entered — integrity proven, principal matched, TTL checked — so this is
       * a trusted negotiation id, and the only question left is whether the human has
       * answered yet.
       */
      const state = ctx.mcpReq.requestState<ProposalState>()
      if (state?.negotiationId) {
        return await collect(
          request,
          state.negotiationId,
          origin,
          ctx,
          server,
          deps
        )
      }

      // Round one. Every guard in `propose` runs before a human is interrupted, so most
      // calls terminate here without ever producing a link.
      const result = await propose(request, {
        fact: args.fact,
        category: args.category,
        suggestedScope: args.suggestedScope,
        projectKey: args.projectKey,
        conversationId: await threadToConversationId(
          auth.clientId,
          args.thread
        ),
      })

      if (result.status !== "input_required") return terminal(result)

      return await askForConsent(
        result.negotiationId,
        args.fact,
        origin,
        ctx,
        server,
        deps
      )
    }
  )
}

/**
 * Turn a settled negotiation into a tool result.
 *
 * None of these are `isError`. "The user declined" is a negotiation that worked and came
 * back no — flagging it as an error invites the model to retry, and the messages already say
 * exactly what to do instead ("Do not retry it.").
 */
function terminal(result: ProposeResult): CallToolResult {
  if (result.status === "committed") {
    return text(describe(result), {
      status: result.status,
      memory: result.memory,
    })
  }
  if (result.status === "input_required") {
    // Unreachable: callers handle this branch before getting here.
    return text("Awaiting the user.", { status: result.status })
  }
  return text(describe(result), { status: result.status })
}

/** Ask the human, out of band, in their own browser. */
async function askForConsent(
  negotiationId: string,
  fact: string,
  origin: string,
  ctx: ServerContext,
  server: McpServer,
  deps: ToolDeps
): Promise<CallToolResult | InputRequiredResult> {
  const url = `${origin}/consent/${negotiationId}`
  const requestState = await deps.codec.mint({ negotiationId }, ctx)

  /**
   * The plain-text path, for a client that cannot render a URL elicitation.
   *
   * Same guarantee, worse ergonomics: the model relays the link, the user approves in the
   * browser, and the outcome surfaces on any later call for the same fact — which lands on
   * `already_known` or `suppressed`, both of which say what happened. Never a form-mode
   * approval, because an answer arriving back through the agent's own connection is not
   * evidence that a human gave it.
   */
  if (!acceptsUrlElicitation(server)) {
    return text(
      `Nothing has been saved. The user must approve this themselves, at:\n${url}\n\n` +
        `Show them that link. Do not call this tool again for the same fact — once they ` +
        `answer, the outcome will be reported the next time it comes up.`,
      { status: "awaiting_user", consentUrl: url }
    )
  }

  return inputRequired({
    inputRequests: {
      consent: inputRequired.elicitUrl({
        url,
        message: `Approve saving "${truncate(fact, 120)}" to memory, and choose how widely it applies.`,
      }),
    },
    requestState,
  })
}

/**
 * Round two: has the human answered?
 *
 * `action: "accept"` on a URL elicitation means only that the user agreed to *open* the
 * link — never that they finished. So the answer comes from the negotiation row, which is
 * the same row the browser writes to, and nothing here trusts the client's report.
 *
 * A still-pending proposal returns `input_required` again carrying the same state and no new
 * `inputRequests`, which the spec defines as "retry when you like". The client polls at its
 * own pace and no isolate is held open waiting on a person.
 */
async function collect(
  request: RequestContext,
  negotiationId: string,
  origin: string,
  ctx: ServerContext,
  server: McpServer,
  deps: ToolDeps
): Promise<CallToolResult | InputRequiredResult> {
  const outcome = await getOutcome(request, negotiationId)
  if (outcome) return terminal(outcome)

  const requestState = await deps.codec.mint({ negotiationId }, ctx)

  if (!acceptsUrlElicitation(server)) {
    return text(
      `Still waiting for the user to answer at ${origin}/consent/${negotiationId}. ` +
        `Nothing has been saved.`,
      { status: "awaiting_user" }
    )
  }

  return inputRequired({ requestState })
}

/**
 * The origin to build the consent link from.
 *
 * Same resolution as everything else (see `resolveOrigin`), and here the reason is concrete:
 * the link has to point at the host whose session cookie the user actually holds. A Worker
 * still reachable at its `*.workers.dev` name would otherwise mint a consent link to an
 * origin where the user has no session, and the page would ask them to sign in on a hostname
 * they have never seen.
 */
function originOf(ctx: ServerContext, env: Env): string {
  const url = ctx.http?.req?.url
  return resolveOrigin(env.BETTER_AUTH_URL, url ?? "http://localhost")
}

function truncate(value: string, max: number): string {
  return value.length <= max ? value : `${value.slice(0, max - 1)}…`
}
